// Seedmap: one map, every layer. Tiles are generated by a pool of workers.
const TILE = 256;
const MIN_BPP = 1, MAX_BPP = 256; // tile levels, in blocks per pixel

const STRUCTS = [
  // id, name, colour, letter, dimension, max blocks-per-pixel to compute at, default on
  [5, 'Village', '#e0913f', 'V', 0, 16, true],
  [1, 'Desert Pyramid', '#e8cf7a', 'D', 0, 8, true],
  [2, 'Jungle Temple', '#5cae45', 'J', 0, 8, true],
  [3, 'Swamp Hut', '#8c78b8', 'H', 0, 8, true],
  [4, 'Igloo', '#dff0ff', 'I', 0, 8, true],
  [10, 'Pillager Outpost', '#a4abb3', 'P', 0, 16, true],
  [8, 'Ocean Monument', '#39d4c4', 'M', 0, 64, true],
  [9, 'Woodland Mansion', '#b0643c', 'W', 0, 128, true],
  [13, 'Ancient City', '#4f7f9c', 'A', 0, 16, true],
  [24, 'Trial Chambers', '#d97a4a', 'C', 0, 8, true],
  [23, 'Trail Ruins', '#c9a27a', 'U', 0, 8, false],
  [6, 'Ocean Ruin', '#5bb8cc', 'R', 0, 4, false],
  [7, 'Shipwreck', '#9c7a52', 'S', 0, 4, false],
  [11, 'Ruined Portal', '#b25ee6', 'p', 0, 4, false],
  [14, 'Buried Treasure', '#f4d648', 'T', 0, 2, false],
  [18, 'Nether Fortress', '#b94343', 'F', -1, 32, true],
  [19, 'Bastion Remnant', '#8a8a8a', 'B', -1, 32, true],
  [12, 'Ruined Portal', '#b25ee6', 'p', -1, 8, false],
  [20, 'End City', '#e3d7ff', 'E', 1, 32, true],
].map(([id, name, color, letter, dim, maxBpp, on]) => ({ id, name, color, letter, dim, maxBpp, on }));

const EXTRA = [
  { key: 'spawn', name: 'World spawn', color: '#ffffff', letter: '★', dim: 0, on: true },
  { key: 'strongholds', name: 'Strongholds', color: '#7bd88f', letter: 'Σ', dim: 0, on: true },
  { key: 'slime', name: 'Slime chunks', color: '#6fdc5a', letter: '', dim: 0, on: false, note: 'zoom in' },
  { key: 'grid', name: 'Chunk / region grid', color: '#666', letter: '', dim: null, on: false },
];

// ---------- state ----------
const $ = (id) => document.getElementById(id);
const canvas = $('canvas'), ctx = canvas.getContext('2d');
const view = { x: 0, z: 0, ppb: 0.25 }; // centre in blocks, pixels per block
const settings = { seed: '0', seedText: '', mc: 28, dim: 0 };
const on = new Set();
let world = null;          // { spawn, strongholds, names, colors } for the current generator
let gen = '';              // generator key
const tiles = new Map();   // key -> { bitmap, ids, cells, found, slime, bpp, tx, tz, used }
const pending = new Map(); // key -> true

// ---------- seeds ----------
function javaHash(s) {
  let h = 0;
  for (const ch of s) h = (Math.imul(31, h) + ch.charCodeAt(0)) | 0;
  return h;
}
function parseSeed(text) {
  const t = text.trim();
  if (t === '') return null;
  if (/^-?\d+$/.test(t)) {
    const n = BigInt(t);
    if (n >= -(2n ** 63n) && n < 2n ** 63n) return BigInt.asUintN(64, n).toString();
  }
  return BigInt.asUintN(64, BigInt(javaHash(t))).toString();
}
const signed = (u) => BigInt.asIntN(64, BigInt(u)).toString();
function randomSeed() {
  const a = new BigUint64Array(1);
  crypto.getRandomValues(a);
  return signed(a[0]);
}

// ---------- workers ----------
const POOL = Math.max(2, Math.min(8, (navigator.hardwareConcurrency || 4) - 1));
const workers = [];
const jobs = [];      // queued tile requests
let reqId = 0;
const waiting = new Map();

function spawnWorker() {
  const w = new Worker('worker.js', { type: 'module' });
  const slot = { w, busy: false, ready: false };
  w.onmessage = ({ data }) => {
    if (data.ready) { slot.ready = true; pump(); return; }
    slot.busy = false;
    const cb = waiting.get(data.id);
    waiting.delete(data.id);
    cb?.(data);
    pump();
  };
  workers.push(slot);
}
for (let i = 0; i < POOL; i++) spawnWorker();

function send(slot, msg, cb) {
  const id = ++reqId;
  slot.busy = true;
  waiting.set(id, cb);
  slot.w.postMessage({ ...msg, id, mc: settings.mc, seed: settings.seed, dim: settings.dim });
}

function pump() {
  // Serve the job closest to the view centre first; drop ones no longer needed.
  for (const slot of workers) {
    if (!slot.ready || slot.busy || !jobs.length) continue;
    const need = visibleKeys();
    for (let i = jobs.length - 1; i >= 0; i--) {
      if (jobs[i].gen !== gen || !need.has(jobs[i].key)) { pending.delete(jobs[i].key); jobs.splice(i, 1); }
    }
    if (!jobs.length) break;
    const cx = view.x, cz = view.z;
    jobs.sort((a, b) => dist2(b, cx, cz) - dist2(a, cx, cz));
    const job = jobs.pop();
    send(slot, job.msg, (r) => {
      pending.delete(job.key);
      if (job.gen !== gen || r.error || !r.bitmap) { if (r.error) console.error(r.error); return; }
      tiles.set(job.key, { ...r, bpp: job.msg.bpp, tx: job.msg.tx, tz: job.msg.tz, used: performance.now() });
      trimCache();
      draw();
    });
  }
  $('busy').hidden = !(jobs.length || workers.some((s) => s.busy));
}
function dist2(job, cx, cz) {
  const span = TILE * job.msg.bpp;
  const dx = (job.msg.tx + 0.5) * span - cx, dz = (job.msg.tz + 0.5) * span - cz;
  return dx * dx + dz * dz;
}
function trimCache() {
  if (tiles.size < 500) return;
  const old = [...tiles.entries()].sort((a, b) => a[1].used - b[1].used).slice(0, 100);
  for (const [k, t] of old) { t.bitmap.close?.(); tiles.delete(k); }
}

// ---------- tiles ----------
const levelBpp = () => {
  let b = 1;
  while (b * 2 <= 1 / view.ppb && b < MAX_BPP) b *= 2;
  return Math.max(MIN_BPP, b);
};
const key = (bpp, tx, tz) => `${gen}:${bpp}:${tx}:${tz}`;

function visibleRange(bpp) {
  const span = TILE * bpp;
  const w = canvas.width / devicePixelRatio, h = canvas.height / devicePixelRatio;
  const x0 = view.x - w / 2 / view.ppb, z0 = view.z - h / 2 / view.ppb;
  const x1 = view.x + w / 2 / view.ppb, z1 = view.z + h / 2 / view.ppb;
  return {
    tx0: Math.floor(x0 / span) - 1, tz0: Math.floor(z0 / span) - 1,
    tx1: Math.floor(x1 / span) + 1, tz1: Math.floor(z1 / span) + 1,
  };
}
function visibleKeys() {
  const bpp = levelBpp(), r = visibleRange(bpp), s = new Set();
  for (let tz = r.tz0; tz <= r.tz1; tz++)
    for (let tx = r.tx0; tx <= r.tx1; tx++) s.add(key(bpp, tx, tz));
  return s;
}

function structsFor(bpp) {
  return STRUCTS.filter((s) => s.dim === settings.dim && bpp <= s.maxBpp).map((s) => s.id);
}

function request() {
  const bpp = levelBpp(), r = visibleRange(bpp);
  for (let tz = r.tz0; tz <= r.tz1; tz++)
    for (let tx = r.tx0; tx <= r.tx1; tx++) {
      const k = key(bpp, tx, tz);
      if (tiles.has(k) || pending.has(k)) continue;
      pending.set(k, true);
      jobs.push({ key: k, gen, msg: { kind: 'tile', tx, tz, bpp, structs: structsFor(bpp) } });
    }
  pump();
}

// Best available image for a tile: itself, else a coarser ancestor.
function findTile(bpp, tx, tz) {
  for (let b = bpp, x = tx, z = tz; b <= MAX_BPP; b *= 2, x = Math.floor(x / 2), z = Math.floor(z / 2)) {
    const t = tiles.get(key(b, x, z));
    if (t) return t;
  }
  return null;
}

// ---------- drawing ----------
const toScreen = (x, z) => {
  const w = canvas.width / devicePixelRatio, h = canvas.height / devicePixelRatio;
  return [(x - view.x) * view.ppb + w / 2, (z - view.z) * view.ppb + h / 2];
};
const toWorld = (sx, sy) => {
  const w = canvas.width / devicePixelRatio, h = canvas.height / devicePixelRatio;
  return [(sx - w / 2) / view.ppb + view.x, (sy - h / 2) / view.ppb + view.z];
};

let markers = []; // [{sx, sy, r, name, x, z}] for hit testing
let frame = 0;
function draw() {
  if (!frame) frame = requestAnimationFrame(render);
}
function render() {
  frame = 0;
  const dpr = devicePixelRatio;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  const w = canvas.width / dpr, h = canvas.height / dpr;
  ctx.fillStyle = '#0b0c0e';
  ctx.fillRect(0, 0, w, h);
  ctx.imageSmoothingEnabled = false;

  const bpp = levelBpp(), r = visibleRange(bpp), span = TILE * bpp;
  const now = performance.now();
  const shown = [];
  for (let tz = r.tz0; tz <= r.tz1; tz++)
    for (let tx = r.tx0; tx <= r.tx1; tx++) {
      const t = findTile(bpp, tx, tz);
      if (!t) continue;
      t.used = now;
      // Source rectangle within t that covers this tile.
      const tspan = TILE * t.bpp;
      const cellBlocks = tspan / t.cells;
      const sx = (tx * span - t.tx * tspan) / cellBlocks, sz = (tz * span - t.tz * tspan) / cellBlocks;
      const ss = span / cellBlocks;
      const [dx, dy] = toScreen(tx * span, tz * span);
      const ds = span * view.ppb;
      ctx.drawImage(t.bitmap, sx, sz, ss, ss, Math.floor(dx), Math.floor(dy), Math.ceil(ds + 1), Math.ceil(ds + 1));
      if (t.bpp === bpp) shown.push(t);
    }

  if (on.has('slime') && settings.dim === 0 && view.ppb >= 0.5) drawSlime(shown);
  if (on.has('grid')) drawGrid(w, h);
  drawMarkers(shown, w, h);
  updateNearby(shown);
}

function drawSlime(shown) {
  ctx.fillStyle = 'rgba(111,220,90,0.45)';
  const cs = 16 * view.ppb;
  for (const t of shown) {
    if (!t.slime) continue;
    const c = Math.sqrt(t.slime.length), span = TILE * t.bpp;
    for (let j = 0; j < c; j++)
      for (let i = 0; i < c; i++) {
        if (!t.slime[j * c + i]) continue;
        const [x, y] = toScreen(t.tx * span + i * 16, t.tz * span + j * 16);
        ctx.fillRect(x, y, cs, cs);
      }
  }
}

function drawGrid(w, h) {
  const [x0, z0] = toWorld(0, 0), [x1, z1] = toWorld(w, h);
  const line = (step, style) => {
    if (step * view.ppb < 8) return;
    ctx.strokeStyle = style;
    ctx.beginPath();
    for (let x = Math.floor(x0 / step) * step; x <= x1; x += step) {
      const [sx] = toScreen(x, 0); ctx.moveTo(Math.round(sx) + .5, 0); ctx.lineTo(Math.round(sx) + .5, h);
    }
    for (let z = Math.floor(z0 / step) * step; z <= z1; z += step) {
      const [, sy] = toScreen(0, z); ctx.moveTo(0, Math.round(sy) + .5); ctx.lineTo(w, Math.round(sy) + .5);
    }
    ctx.stroke();
  };
  ctx.lineWidth = 1;
  line(16, 'rgba(0,0,0,0.18)');
  line(512, 'rgba(0,0,0,0.5)');
}

function marker(x, z, color, letter, name, w, h, size = 9) {
  const [sx, sy] = toScreen(x, z);
  if (sx < -20 || sy < -20 || sx > w + 20 || sy > h + 20) return;
  ctx.beginPath();
  ctx.arc(sx, sy, size, 0, Math.PI * 2);
  ctx.fillStyle = color;
  ctx.fill();
  ctx.lineWidth = 2;
  ctx.strokeStyle = 'rgba(0,0,0,0.75)';
  ctx.stroke();
  if (letter) {
    ctx.fillStyle = '#111';
    ctx.font = `700 ${size + 1}px system-ui, sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(letter, sx, sy + 0.5);
  }
  markers.push({ sx, sy, r: size + 2, name, x, z });
}

const structById = new Map(STRUCTS.map((s) => [s.id, s]));
function drawMarkers(shown, w, h) {
  markers = [];
  for (const t of shown)
    for (const f of t.found) {
      const s = structById.get(f.t);
      if (s && on.has(`s${s.id}`) && s.dim === settings.dim) marker(f.x, f.z, s.color, s.letter, s.name, w, h);
    }
  if (world && settings.dim === 0) {
    if (on.has('strongholds'))
      world.strongholds.forEach(([x, z], i) => marker(x, z, '#7bd88f', 'Σ', `Stronghold #${i + 1}`, w, h, 10));
    if (on.has('spawn')) marker(world.spawn[0], world.spawn[1], '#ffffff', '★', 'World spawn', w, h, 11);
  }
}

// ---------- nearby list ----------
let nearbySig = '';
function updateNearby(shown) {
  const items = [];
  const push = (name, color, letter, x, z) =>
    items.push({ name, color, letter, x, z, d: Math.hypot(x - view.x, z - view.z) });
  const seen = new Set();
  for (const [k, t] of tiles) {
    if (!k.startsWith(gen + ':')) continue;
    for (const f of t.found) {
      const s = structById.get(f.t);
      const id = `${f.t}:${f.x}:${f.z}`;
      if (!s || seen.has(id) || !on.has(`s${s.id}`) || s.dim !== settings.dim) continue;
      seen.add(id);
      push(s.name, s.color, s.letter, f.x, f.z);
    }
  }
  if (world && settings.dim === 0 && on.has('strongholds'))
    world.strongholds.forEach(([x, z], i) => push(`Stronghold #${i + 1}`, '#7bd88f', 'Σ', x, z));

  // Keep the closest of each kind, then the closest overall.
  items.sort((a, b) => a.d - b.d);
  const byKind = new Map();
  for (const it of items) if (!byKind.has(it.name.replace(/ #\d+$/, ''))) byKind.set(it.name.replace(/ #\d+$/, ''), it);
  const list = [...byKind.values()].slice(0, 12);
  const sig = list.map((i) => `${i.name}${i.x}${i.z}`).join() + Math.round(view.x / 16) + Math.round(view.z / 16);
  if (sig === nearbySig) return;
  nearbySig = sig;
  const ol = $('nearby');
  ol.replaceChildren(...(list.length ? list.map((it) => {
    const li = document.createElement('li');
    li.innerHTML = `<span class="swatch" style="background:${it.color}">${it.letter}</span>
      <span>${it.name}<br><small style="color:var(--muted)">${it.x}, ${it.z}</small></span>
      <span class="d">${Math.round(it.d)} m</span>`;
    li.onclick = () => flyTo(it.x, it.z);
    return li;
  }) : [Object.assign(document.createElement('li'), { className: 'empty', textContent: 'Nothing loaded nearby yet.' })]));
}

// ---------- world / regenerate ----------
function regenerate() {
  gen = `${settings.mc}|${settings.seed}|${settings.dim}`;
  world = null;
  jobs.length = 0;
  pending.clear();
  for (const [k, t] of tiles) if (!k.startsWith(gen + ':')) { t.bitmap.close?.(); tiles.delete(k); }
  const g = gen;
  const ask = () => {
    const slot = workers.find((s) => s.ready && !s.busy);
    if (!slot) return setTimeout(ask, 30);
    send(slot, { kind: 'world', strongholds: settings.dim === 0 }, (r) => {
      if (g !== gen) return;
      world = r;
      nearbySig = '';
      draw();
    });
  };
  ask();
  request();
  draw();
  saveHash();
}

// ---------- layers UI ----------
function buildLayers() {
  const box = $('layers');
  box.replaceChildren();
  const add = (id, item) => {
    const label = document.createElement('label');
    const dimOk = item.dim === null || item.dim === settings.dim;
    label.className = dimOk ? '' : 'off-dim';
    label.innerHTML = `<input type="checkbox"${on.has(id) ? ' checked' : ''}>
      <span class="swatch" style="background:${item.color}">${item.letter}</span>
      <span>${item.name}${item.note ? ` <small style="color:var(--muted)">(${item.note})</small>` : ''}</span>`;
    label.querySelector('input').onchange = (e) => {
      e.target.checked ? on.add(id) : on.delete(id);
      nearbySig = '';
      saveHash();
      draw();
    };
    return label;
  };
  const group = (title, els) => {
    if (!els.length) return;
    box.append(Object.assign(document.createElement('div'), { className: 'group', textContent: title }), ...els);
  };
  group('World', EXTRA.filter((e) => e.dim === null || e.dim === settings.dim).map((e) => add(e.key, e)));
  group('Structures', STRUCTS.filter((s) => s.dim === settings.dim).map((s) => add(`s${s.id}`, s)));
}

// ---------- URL state ----------
function saveHash() {
  const p = new URLSearchParams({
    seed: settings.seedText || signed(settings.seed),
    v: settings.mc, d: settings.dim,
    x: Math.round(view.x), z: Math.round(view.z),
    zoom: +Math.log2(view.ppb).toFixed(2),
    l: [...on].join('.'),
  });
  history.replaceState(null, '', '#' + p);
}
function loadHash() {
  const p = new URLSearchParams(location.hash.slice(1));
  const seedText = p.get('seed') ?? randomSeed();
  setSeedText(seedText);
  if (p.has('v')) settings.mc = +p.get('v');
  if (p.has('d')) settings.dim = +p.get('d');
  if (p.has('x')) view.x = +p.get('x');
  if (p.has('z')) view.z = +p.get('z');
  if (p.has('zoom')) view.ppb = clampZoom(2 ** +p.get('zoom'));
  on.clear();
  if (p.has('l')) p.get('l').split('.').filter(Boolean).forEach((k) => on.add(k));
  else {
    EXTRA.filter((e) => e.on).forEach((e) => on.add(e.key));
    STRUCTS.filter((s) => s.on).forEach((s) => on.add(`s${s.id}`));
  }
  $('version').value = settings.mc;
  $('dim').value = settings.dim;
}
function setSeedText(t) {
  const seed = parseSeed(t) ?? parseSeed(randomSeed());
  settings.seed = seed;
  settings.seedText = /^-?\d+$/.test(t.trim()) ? signed(seed) : t.trim();
  $('seed').value = settings.seedText;
}

// ---------- interaction ----------
const clampZoom = (z) => Math.min(8, Math.max(1 / 512, z));
function zoomAt(factor, sx, sy) {
  const [wx, wz] = toWorld(sx, sy);
  view.ppb = clampZoom(view.ppb * factor);
  const [nx, nz] = toWorld(sx, sy);
  view.x += wx - nx;
  view.z += wz - nz;
  changed();
}
let hashTimer = 0;
function changed() {
  request();
  draw();
  clearTimeout(hashTimer);
  hashTimer = setTimeout(saveHash, 250);
}
function flyTo(x, z) {
  view.x = x; view.z = z;
  if (view.ppb < 0.25) view.ppb = 0.25;
  changed();
}

const pointers = new Map();
let pinch = null, moved = false;
canvas.addEventListener('pointerdown', (e) => {
  canvas.setPointerCapture(e.pointerId);
  pointers.set(e.pointerId, [e.offsetX, e.offsetY]);
  moved = false;
  canvas.classList.add('dragging');
  if (pointers.size === 2) {
    const [a, b] = [...pointers.values()];
    pinch = { d: Math.hypot(a[0] - b[0], a[1] - b[1]) };
  }
});
canvas.addEventListener('pointermove', (e) => {
  const prev = pointers.get(e.pointerId);
  hover(e.offsetX, e.offsetY);
  if (!prev) return;
  const cur = [e.offsetX, e.offsetY];
  pointers.set(e.pointerId, cur);
  if (pointers.size === 2 && pinch) {
    const [a, b] = [...pointers.values()];
    const d = Math.hypot(a[0] - b[0], a[1] - b[1]);
    zoomAt(d / pinch.d, (a[0] + b[0]) / 2, (a[1] + b[1]) / 2);
    pinch.d = d;
    return;
  }
  const dx = cur[0] - prev[0], dy = cur[1] - prev[1];
  if (Math.abs(dx) + Math.abs(dy) > 0) moved = true;
  view.x -= dx / view.ppb;
  view.z -= dy / view.ppb;
  changed();
});
const up = (e) => {
  pointers.delete(e.pointerId);
  if (pointers.size < 2) pinch = null;
  if (!pointers.size) canvas.classList.remove('dragging');
};
canvas.addEventListener('pointerup', (e) => {
  if (!moved) click(e.offsetX, e.offsetY);
  up(e);
});
canvas.addEventListener('pointercancel', up);
canvas.addEventListener('pointerleave', () => { $('tooltip').hidden = true; });
canvas.addEventListener('wheel', (e) => {
  e.preventDefault();
  zoomAt(Math.exp(-e.deltaY * (e.ctrlKey ? 0.01 : 0.0015)), e.offsetX, e.offsetY);
}, { passive: false });

function hitMarker(sx, sy) {
  for (let i = markers.length - 1; i >= 0; i--) {
    const m = markers[i];
    if (Math.hypot(m.sx - sx, m.sy - sy) <= m.r) return m;
  }
  return null;
}
function biomeAt(x, z) {
  const bpp = levelBpp(), span = TILE * bpp;
  const t = findTile(bpp, Math.floor(x / span), Math.floor(z / span));
  if (!t) return null;
  const tspan = TILE * t.bpp, cb = tspan / t.cells;
  const i = Math.floor((x - t.tx * tspan) / cb), j = Math.floor((z - t.tz * tspan) / cb);
  if (i < 0 || j < 0 || i >= t.cells || j >= t.cells) return null;
  return t.ids[j * t.cells + i];
}
const pretty = (s) => s.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
function hover(sx, sy) {
  const [x, z] = toWorld(sx, sy);
  $('coords').textContent = `${Math.floor(x)}, ${Math.floor(z)}`;
  const id = biomeAt(x, z);
  $('biome').textContent = world && id != null && world.names[id] ? pretty(world.names[id]) : '';
  const m = hitMarker(sx, sy);
  const tip = $('tooltip');
  if (m) {
    tip.innerHTML = `${m.name}<small>${m.x}, ${m.z} · click to copy /tp</small>`;
    tip.style.left = sx + 'px';
    tip.style.top = sy + 'px';
    tip.hidden = false;
  } else tip.hidden = true;
}
async function click(sx, sy) {
  const m = hitMarker(sx, sy);
  if (!m) return;
  const cmd = `/tp @s ${m.x} ~ ${m.z}`;
  try { await navigator.clipboard.writeText(cmd); } catch {}
  $('tooltip').innerHTML = `Copied <code>${cmd}</code>`;
}

// ---------- controls ----------
$('seed').addEventListener('change', (e) => { setSeedText(e.target.value); regenerate(); });
$('random').onclick = () => { setSeedText(randomSeed()); regenerate(); };
$('version').onchange = (e) => { settings.mc = +e.target.value; regenerate(); };
$('dim').onchange = (e) => {
  const next = +e.target.value, prev = settings.dim;
  // Keep the same place in the world when hopping to/from the Nether.
  if (prev === 0 && next === -1) { view.x /= 8; view.z /= 8; }
  if (prev === -1 && next === 0) { view.x *= 8; view.z *= 8; }
  settings.dim = next;
  buildLayers();
  regenerate();
};
$('goto').onsubmit = (e) => {
  e.preventDefault();
  const x = parseFloat($('goto-x').value), z = parseFloat($('goto-z').value);
  if (Number.isFinite(x) && Number.isFinite(z)) flyTo(x, z);
};
const centre = () => [canvas.clientWidth / 2, canvas.clientHeight / 2];
$('zoom-in').onclick = () => zoomAt(2, ...centre());
$('zoom-out').onclick = () => zoomAt(0.5, ...centre());
$('share').onclick = async () => {
  saveHash();
  try { await navigator.clipboard.writeText(location.href); $('share').textContent = 'Copied'; } catch {}
  setTimeout(() => ($('share').textContent = 'Share'), 1200);
};
$('toggle-panel').onclick = () => $('panel').classList.toggle('collapsed');
window.addEventListener('keydown', (e) => {
  if (e.target.matches('input, select')) return;
  if (e.key === '+' || e.key === '=') zoomAt(2, ...centre());
  if (e.key === '-') zoomAt(0.5, ...centre());
});

function resize() {
  const dpr = devicePixelRatio;
  canvas.width = Math.round(canvas.clientWidth * dpr);
  canvas.height = Math.round(canvas.clientHeight * dpr);
  changed();
}
new ResizeObserver(resize).observe(canvas);

loadHash();
buildLayers();
regenerate();
